<?php
require __DIR__.'/ui.php';role(['admin','gerente','caixa']);$p=db();$month=$_GET['month']??date('Y-m');
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(isset($_POST['expense']))$p->prepare("INSERT INTO expenses(description,category,amount,expense_date,fixed_cost)VALUES(?,?,?,?,?)")->execute([$_POST['description'],$_POST['category'],$_POST['amount'],$_POST['expense_date'],isset($_POST['fixed_cost'])?1:0]);if(isset($_POST['receive']))$p->prepare("UPDATE receivables SET status='Recebido',paid_at=datetime('now','localtime') WHERE id=?")->execute([$_POST['receive']]);go('finance.php?month='.$month);}
$s=$p->prepare("SELECT COALESCE(SUM(total),0) FROM orders WHERE substr(created_at,1,7)=? AND status<>'Cancelado'");$s->execute([$month]);$revenue=(float)$s->fetchColumn();$s=$p->prepare("SELECT COALESCE(SUM(cost),0) FROM orders WHERE substr(created_at,1,7)=? AND status<>'Cancelado'");$s->execute([$month]);$cogs=(float)$s->fetchColumn();$s=$p->prepare("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE substr(expense_date,1,7)=?");$s->execute([$month]);$expenses=(float)$s->fetchColumn();$loss=(float)$p->query("SELECT COALESCE(SUM(cost),0) FROM losses WHERE substr(loss_date,1,7)='$month'")->fetchColumn();$net=$revenue-$cogs-$expenses-$loss;$rec=$p->query("SELECT r.*,o.number,c.name customer FROM receivables r LEFT JOIN orders o ON o.id=r.order_id LEFT JOIN customers c ON c.id=r.customer_id ORDER BY r.id DESC")->fetchAll();page_head('Financeiro / DRE');?>
<div class="card"><form><label>Mês</label><input style="max-width:220px" type="month" name="month" value="<?=e($month)?>" onchange="this.form.submit()"></form></div>
<div class="grid g4"><div class="card kpi"><span>Receita</span><strong><?=money($revenue)?></strong></div><div class="card kpi"><span>Custo dos produtos</span><strong><?=money($cogs)?></strong></div><div class="card kpi"><span>Despesas + perdas</span><strong><?=money($expenses+$loss)?></strong></div><div class="card kpi"><span>Resultado líquido</span><strong><?=money($net)?></strong></div></div>
<div class="grid g2"><div class="card"><h2>Contas a receber</h2><div class="table"><table><tr><th>Pedido</th><th>Cliente</th><th>Valor</th><th>Status</th><th></th></tr><?php foreach($rec as $r):?><tr><td><?=e($r['number'])?></td><td><?=e($r['customer'])?></td><td><?=money($r['amount'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']!=='Recebido'):?><form method="post"><?=csrf_field()?><button name="receive" value="<?=$r['id']?>" class="green">Receber</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div>
<div class="card"><h2>Registrar despesa</h2><form method="post"><?=csrf_field()?><input type="hidden" name="expense" value="1"><label>Descrição</label><input name="description"><label>Categoria</label><input name="category"><div class="grid g2"><div><label>Valor</label><input name="amount" type="number" step=".01"></div><div><label>Data</label><input name="expense_date" type="date" value="<?=date('Y-m-d')?>"></div></div><label><input style="width:auto" type="checkbox" name="fixed_cost"> Custo fixo</label><button class="primary">Salvar</button></form></div></div><?php page_foot();?>